"""HealthReportingMixin for agent health and error reporting."""
import asyncio
import time
from typing import Any


class HealthReportingMixin:
    """Mixin for health reporting and error handling.

    Extracted from 21+ actor files to remove ~880 lines of duplication.
    """

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._error_count = 0
        self._last_health_check = 0.0
        self._health_status = "healthy"
        self._spawn_time = time.monotonic()

    def get_health_status(self) -> dict[str, Any]:
        """Get current health status."""
        return {
            "status": self._health_status,
            "error_count": self._error_count,
            "last_health_check": self._last_health_check,
            "agent_id": getattr(self, "agent_id", "unknown"),
            "uptime": time.monotonic() - self._spawn_time,
        }

    def record_error(
        self,
        error: Exception,
        context: dict[str, Any] | None = None
    ) -> None:
        """Record an error for health tracking."""
        self._error_count += 1
        if self._error_count >= 10:
            self._health_status = "critical"
        elif self._error_count >= 5:
            self._health_status = "degraded"
        elif self._error_count >= 1:
            self._health_status = "warning"

        error_data = {
            "error_type": type(error).__name__,
            "error_message": str(error),
            "agent_id": getattr(self, "agent_id", "unknown"),
            "context": context or {},
        }
        self.logger.error(
            f"Agent error: {error_data['error_type']} - {error_data['error_message']}",
            extra=error_data
        )

    def reset_error_count(self) -> None:
        """Reset error count after recovery."""
        self._error_count = 0
        self._health_status = "healthy"

    async def health_check(self) -> dict[str, Any]:
        """Perform health check."""
        self._last_health_check = asyncio.get_event_loop().time()
        health_data = self.get_health_status()
        subsystem_health = {}

        if hasattr(self, "_memory_system"):
            subsystem_health["memory"] = await self._check_memory_health()
        if hasattr(self, "_consensus_client"):
            subsystem_health["consensus"] = await self._check_consensus_health()
        if hasattr(self, "_pattern_client"):
            subsystem_health["patterns"] = await self._check_pattern_health()

        health_data["subsystems"] = subsystem_health

        await self._emit_pattern(
            pattern_type="health_report",
            data=health_data
        )
        return health_data

    async def _check_memory_health(self) -> bool:
        """Check memory subsystem health."""
        try:
            if hasattr(self, "_memory_system"):
                await self._memory_system.ping()
                return True
        except Exception:
            return False
        return True

    async def _check_consensus_health(self) -> bool:
        """Check consensus subsystem health."""
        try:
            if hasattr(self, "_consensus_client"):
                return self._consensus_client.is_connected()
        except Exception:
            return False
        return True

    async def _check_pattern_health(self) -> bool:
        """Check pattern subsystem health."""
        try:
            if hasattr(self, "_pattern_client"):
                return self._pattern_client.is_connected()
        except Exception:
            return False
        return True

    def get_error_history(self, limit: int = 10) -> list[dict[str, Any]]:
        """Get recent error history."""
        return [
            {
                "agent_id": getattr(self, "agent_id", "unknown"),
                "total_errors": self._error_count,
                "status": self._health_status,
            }
        ]

"""MemoryAccessMixin for agent memory operations."""
import asyncio
from typing import Any


class MemoryAccessMixin:
    """Mixin for memory access and tracking.

    Extracted from 16 actor files to remove ~544 lines of duplication.
    """

    async def _track_memory_access(
        self,
        memory_id: str,
        access_type: str,
        metadata: dict[str, Any] | None = None
    ) -> None:
        """Track memory access for observability."""
        access_record = {
            "memory_id": memory_id,
            "access_type": access_type,
            "agent_id": getattr(self, "agent_id", "unknown"),
            "timestamp": asyncio.get_event_loop().time(),
            "metadata": metadata or {},
        }
        try:
            if hasattr(self, "_memory_access_logger"):
                await self._memory_access_logger.log(access_record)
        except Exception as e:
            self.logger.debug(f"Memory access tracking failed: {e}")

    async def _get_memory_tier(self, memory_type: str = "episodic") -> str:
        """Get memory tier for specified memory type."""
        tier_mapping = {
            "working": "tier-1",
            "episodic": "tier-2",
            "semantic": "tier-3",
        }
        return tier_mapping.get(memory_type, "tier-2")

    async def _fetch_from_memory(
        self,
        query: str,
        memory_type: str | None = None,
        limit: int = 5
    ) -> list[dict[str, Any]]:
        """Fetch memories matching query."""
        try:
            if hasattr(self, "_memory_system"):
                memories = await self._memory_system.search(
                    query=query,
                    memory_type=memory_type,
                    limit=limit
                )
                for memory in memories:
                    await self._track_memory_access(
                        memory_id=memory.get("id"),
                        access_type="read"
                    )
                return memories
        except Exception as e:
            self.logger.warning(f"Memory fetch failed: {e}")
        return []

    async def _store_to_memory(
        self,
        content: str,
        memory_type: str = "episodic",
        metadata: dict[str, Any] | None = None
    ) -> str | None:
        """Store content to memory."""
        try:
            if hasattr(self, "_memory_system"):
                memory_id = await self._memory_system.store(
                    content=content,
                    memory_type=memory_type,
                    metadata=metadata or {}
                )
                await self._track_memory_access(
                    memory_id=memory_id,
                    access_type="write"
                )
                return memory_id
        except Exception as e:
            self.logger.warning(f"Memory store failed: {e}")
        return None

